s=s.replace("const renderer=new THREE.WebGLRenderer({antialias:true,powerPreference:'high-performance'});","let renderer;try{renderer=new THREE.WebGLRenderer({antialias:true,powerPreference:'high-performance'});}catch(error){errorEl.hidden=false;errorEl.textContent='三维渲染未启动：当前浏览器未提供可用 WebGL。没有用旧画面或图片替代。\\n'+String(error.message);throw error;}")
